{
  "missionStatement": "Study existing repository documents and conduct online research on room-temperature superconductivity, then propose novel chemistry and physics for discovering and manufacturing room-temperature superconducting compounds, updating the repository's documentation and code accordingly.",
  "criteria": [
    {
      "description": "Literature review is updated with findings from online research, including at least five recent papers (2020+) on hydride superconductors and other promising systems.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "Online research summary document is updated with structured summaries of key papers, including transition temperatures, synthesis conditions, and open questions.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "Proposed chemistry and physics document includes at least three new candidate material families with predicted Tc > 300 K, along with underlying mechanisms and synthesis routes.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Candidate materials list is updated with new compounds, their predicted properties, and references to online research.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "Theoretical framework document is updated to incorporate new models (e.g., BCS-like, excitonic, or novel mechanisms) derived from online research.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "Discovery strategy document outlines a prioritized screening approach for new compounds, including computational and experimental steps.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "Synthesis methods document includes high-pressure synthesis protocols for hydride materials and other relevant techniques.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "Characterization techniques document adds methods for measuring Tc under high pressure and other relevant diagnostics.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "Roadmap document is updated with new milestones and timelines based on research findings and proposed experiments.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "Novel mechanism document is updated with detailed description of any new proposed superconducting mechanism.",
      "expectedFiles": ["docs/novel_mechanism.md"]
    },
    {
      "description": "Experimental protocol for hydride synthesis is updated with step-by-step procedures based on online research.",
      "expectedFiles": ["docs/experimental_protocol_hydride.md"]
    },
    {
      "description": "Manufacturing scalability document discusses challenges and potential solutions for scaling up synthesis of new compounds.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Challenges and mitigations document is updated with new risks and countermeasures identified from online research.",
      "expectedFiles": ["docs/challenges_and_mitigations.md"]
    },
    {
      "description": "Superconductor database is extended with at least 10 new entries from online research, including Tc, pressure, and composition.",
      "expectedFiles": ["data/superconductor_database.json"]
    },
    {
      "description": "Prediction script is updated to include new predictive models or features based on research findings.",
      "expectedFiles": ["scripts/predict_tc.py"]
    },
    {
      "description": "Query database script is updated to support new fields or filtering criteria.",
      "expectedFiles": ["scripts/query_database.py"]
    },
    {
      "description": "Tests for prediction script pass and cover any new functions added.",
      "expectedFiles": ["tests/test_predict_tc.py"]
    },
    {
      "description": "Tests for query database script pass and cover any new functionality.",
      "expectedFiles": ["tests/test_query_database.py"]
    },
    {
      "description": "README is updated to reflect new findings and any changes to the repository structure.",
      "expectedFiles": ["README.md"]
    }
  ]
}

{
