    {
      "description": "Candidate materials list is revised to include promising compounds identified in online research (e.g., ternary hydrides, carbonaceous sulfur hydride, nickelates) with their predicted Tc and synthesis feasibility.",
      "expectedFiles": ["candidate_materials.md"]
