    {
      "description": "Proposed chemistry and physics document is rewritten to present a coherent strategy for discovering and manufacturing room-temperature superconducting compounds, integrating insights from all other documents.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Manufacturing scalability document is created or updated to address challenges in scaling up synthesis from lab to industrial production, including cost, safety, and material stability.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Experimental protocol for hydride superconductors is updated with step-by-step procedures for high-pressure synthesis and characterization.",
      "expectedFiles": ["docs/experimental_protocol_hydride.md"]
    },
    {
      "description": "Novel mechanism document is created or updated to propose new theoretical mechanisms (e.g., excitonic, plasmonic, or topological) that could enable room-temperature superconductivity.",
      "expectedFiles": ["docs/novel_mechanism.md"]
    },
    {
      "description": "Discovery strategy document is updated to outline a systematic screening approach using computational predictions (e.g., density functional theory, machine learning) and experimental validation.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "Roadmap document is updated with concrete milestones, timelines, and resource requirements for the next 3-5 years of research.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "All new or updated documents include citations to primary sources (journal articles, preprints) with URLs and key data points.",
      "expectedFiles": []
    },
    {
      "description": "A new script or notebook is added to predict Tc for candidate materials using a simple empirical formula or machine learning model, with unit tests.",
      "expectedFiles": ["scripts/predict_tc.py", "tests/test_predict_tc.py"]
    },
    {
      "description": "The superconductor database JSON is updated with new entries from online research, including material name, composition, Tc, pressure, and reference.",
      "expectedFiles": ["data/superconductor_database.json"]
    }
  ]
}

